from typing import List
class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10 ** 9 + 7
        cnt = [0] * 31
        for v in nums:
            for b in range(31):
                if v >> b & 1:
                    cnt[b] += 1
        ans = 0
        for _ in range(k):
            x = 0
            for b in range(30, -1, -1):
                if cnt[b]:
                    x |= 1 << b
                    cnt[b] -= 1
            ans = (ans + x * x) % MOD
        return ans

