class Solution {
public:
    int maxSum(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        int cnt[31] = {};
        for (int v : nums)
            for (int b = 0; b < 31; b++)
                if (v >> b & 1) cnt[b]++;
        long long ans = 0;
        for (int t = 0; t < k; t++) {
            long long x = 0;
            for (int b = 30; b >= 0; b--)
                if (cnt[b]) { x |= 1LL << b; cnt[b]--; }
            ans = (ans + x % MOD * (x % MOD)) % MOD;
        }
        return (int)ans;
    }
};

