class Solution {
    public int maxSum(int[] nums, int k) {
        final long MOD = 1_000_000_007L;
        int[] cnt = new int[31];
        for (int v : nums)
            for (int b = 0; b < 31; b++)
                if ((v >> b & 1) == 1) cnt[b]++;
        long ans = 0;
        for (int t = 0; t < k; t++) {
            long x = 0;
            for (int b = 30; b >= 0; b--)
                if (cnt[b] > 0) { x |= 1L << b; cnt[b]--; }
            ans = (ans + x % MOD * (x % MOD)) % MOD;
        }
        return (int) ans;
    }
}

