var maxSum = function(nums, k) {
    const MOD = 1e9 + 7;
    const cnt = new Array(31).fill(0);
    for (const v of nums)
        for (let b = 0; b < 31; b++)
            if ((v >> b) & 1) cnt[b]++;
    let ans = 0;
    for (let t = 0; t < k; t++) {
        let x = 0;
        for (let b = 30; b >= 0; b--)
            if (cnt[b] > 0) { x |= 1 << b; cnt[b]--; }
        ans = (ans + Number(BigInt(x) * BigInt(x) % BigInt(MOD))) % MOD;
    }
    return ans;
};
